package org.tvbuttons.free;
import java.util.*;
public final class ActionCatalog {
 public static final String[] BASIC={"power","settings","inputs","rewind","play","ff","mute","volup","voldown","back","home","alice","none","recents","previous","closeapp","restartapp","wifi","bluetooth","mouse","scrollup","scrolldown","next","prev","channelup","channeldown","picture","sound"};
 public static final String[] ADVANCED={"screenshot","timer","canceltimer","sleep","black","clock","link","macro"};
 public static String label(String a){if(a.startsWith("timer:"))return "Таймер сна: "+a.substring(6)+" мин";if(a.startsWith("link:"))return "Открыть ссылку";if(a.startsWith("macro:"))return "Макрос";if(a.startsWith("hdmi:"))return "HDMI "+a.substring(5);switch(a){case "power":return "Включить / выключить ТВ";case "none":return "Ничего не делать";case "home":return "Домой";case "back":return "Назад";case "recents":return "Недавние приложения";case "previous":return "Предыдущее приложение";case "closeapp":return "Закрыть текущее приложение";case "restartapp":return "Перезапустить текущее приложение";case "settings":return "Настройки ТВ";case "wifi":return "Настройки Wi-Fi";case "bluetooth":return "Подключить Bluetooth-устройство";case "mouse":return "Мышь с пульта — включить / выключить";case "scrollup":return "Прокрутить вверх";case "scrolldown":return "Прокрутить вниз";case "volup":return "Увеличить громкость";case "voldown":return "Уменьшить громкость";case "mute":return "Отключить / включить звук";case "play":return "Пауза / воспроизведение";case "next":return "Следующий трек";case "prev":return "Предыдущий трек";case "ff":return "Перемотка вперёд";case "rewind":return "Перемотка назад";case "channelup":return "Следующий канал";case "channeldown":return "Предыдущий канал";case "inputs":return "Выбор входа HDMI";case "alice":return "Голосовой помощник (Алиса)";case "picture":return "Настройки изображения";case "sound":return "Настройки звука";case "screenshot":return "Сделать скриншот";case "timer":return "Таймер сна…";case "canceltimer":return "Отменить таймер сна";case "sleep":return "Перевести ТВ в сон";case "black":return "Чёрный экран со звуком — вкл. / выкл.";case "clock":return "Часы поверх изображения — вкл. / выкл.";case "link":return "Открыть ссылку…";case "macro":return "Макрос из нескольких действий…";case "":return "Не назначено";default:return "Неизвестное действие";}}
}
